//! The `sherlock_shell_v1` protocol: windows and screens for the programs of the shell (bar,
//! dock), described in `protocol/sherlock-shell-v1.xml` and ADR 0021. The bindings are
//! generated by `wayland-scanner`: `client` with the `client` feature, `server` with the
//! `server` feature.
//!
//! The compositor only offers the protocol on its shell socket: the session's Wayland socket
//! followed by [`SOCKET_SUFFIX`], in the same directory.

use std::path::{Path, PathBuf};

/// What the shell socket adds to the name of the session's Wayland socket.
pub const SOCKET_SUFFIX: &str = "-shell";

/// Path of the shell socket next to the Wayland socket at `socket`.
pub fn socket_path(socket: &Path) -> PathBuf {
    let mut path = socket.as_os_str().to_owned();
    path.push(SOCKET_SUFFIX);
    PathBuf::from(path)
}

/// Path of the shell socket of the session that `WAYLAND_DISPLAY` names: a name relative to
/// `XDG_RUNTIME_DIR`, or an absolute path. `None` when the environment does not say.
pub fn socket_from_env() -> Option<PathBuf> {
    let display = PathBuf::from(std::env::var_os("WAYLAND_DISPLAY")?);
    let socket = if display.is_absolute() {
        display
    } else {
        PathBuf::from(std::env::var_os("XDG_RUNTIME_DIR")?).join(display)
    };
    Some(socket_path(&socket))
}

// The macros read the XML at build time, which cargo does not track: including it here makes a
// change of the protocol rebuild the bindings.
const _: &str = include_str!("../protocol/sherlock-shell-v1.xml");

// Generated code: the lints of the workspace do not apply to it.
#[allow(
    dead_code,
    missing_docs,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    unused_imports,
    unused_unsafe,
    unused_variables,
    clippy::all,
    clippy::pedantic,
    clippy::undocumented_unsafe_blocks
)]
mod generated {
    /// Client side of the protocol.
    #[cfg(feature = "client")]
    pub mod client {
        use wayland_client;
        use wayland_client::protocol::*;

        pub mod __interfaces {
            use wayland_client::protocol::__interfaces::*;
            wayland_scanner::generate_interfaces!("protocol/sherlock-shell-v1.xml");
        }
        use self::__interfaces::*;

        wayland_scanner::generate_client_code!("protocol/sherlock-shell-v1.xml");
    }

    /// Server side of the protocol.
    #[cfg(feature = "server")]
    pub mod server {
        use wayland_server;
        use wayland_server::protocol::*;

        pub mod __interfaces {
            use wayland_server::protocol::__interfaces::*;
            wayland_scanner::generate_interfaces!("protocol/sherlock-shell-v1.xml");
        }
        use self::__interfaces::*;

        wayland_scanner::generate_server_code!("protocol/sherlock-shell-v1.xml");
    }
}

#[cfg(feature = "client")]
pub use generated::client;
#[cfg(feature = "server")]
pub use generated::server;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_shell_socket_sits_next_to_the_session_socket() {
        assert_eq!(
            socket_path(Path::new("/run/user/1000/wayland-1")),
            PathBuf::from("/run/user/1000/wayland-1-shell")
        );
    }
}
